uint32_t key[4];

uint32_t getleft(uint64_t x) { return (x >> 32) & 0xFFFFFFFF; }
uint32_t getright(uint64_t x) { return x & 0xFFFFFFFF; }
uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }
uint32_t expand(uint32_t k) { return k ^ (k << 16) ^ (k * 12345); }

uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t temp = (a + b + x) & 0xFF;
    return ((temp << 2) | (temp >> 6)) & 0xFF;
}

uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1] ^ x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);
    uint32_t out = 0;
    for (int i = 0; i < 4; i++) out |= (uint32_t)y[i] << (8 * i);
    return out;
}

uint64_t try_last(uint64_t c, uint32_t k3) {
    uint32_t L = getright(c), R = getleft(c);
    L ^= R;
    uint32_t t = L; L = R; R = t; L ^= f_function(t ^ k3);
    t = L; L = R; R = t; L ^= f_function(t ^ key[2]);
    return merge(L, R);
}

int main(void) {
    uint64_t pt[32], ct[32];
    FILE *fp = fopen("pairs.txt", "r");
    for (int i = 0; i < 32; i++) if (fscanf(fp, "%lu %lu", &pt[i], &ct[i]) != 2) return 1;
    fclose(fp);

    for (uint32_t s3 = 0; s3 < (1u << 20); s3++) {
        uint32_t k3 = expand(s3);
        if (try_last(ct[0], k3) != pt[0]) continue;
        for (int i = 1; i < 32; i++) if (try_last(ct[i], k3) != pt[i]) break;
        if (i == 32) {
            fprintf(stderr, "k3 seed %x\n", s3);
            /* recover the rest from the first pair */
            uint32_t L = getright(ct[0]), R = getleft(ct[0]);
            L ^= R;
            uint32_t t = L; L = R; R = t; L ^= f_function(t ^ k3);
            /* L R now equal the state after round 2; use a second pair if desired */
            for (uint32_t s2 = 0; s2 < (1u << 20); s2++) {
                uint32_t k2 = expand(s2);
                t = L; L = R; R = t; L ^= f_function(t ^ k2);
                if (L == getleft(merge(getleft(ct[0]), getright(ct[0])))) break;
            }
            break;
        }
    }
    return 0;
}
