#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>

uint32_t getleft(uint64_t x) { return (x >> 32) & 0xFFFFFFFF; }
uint32_t getright(uint64_t x) { return x & 0xFFFFFFFF; }
uint64_t merge(uint32_t l, uint32_t r) { return ((uint64_t)l << 32) | r; }
uint32_t expand(uint32_t k) { return k ^ (k << 16) ^ (k * 12345); }

uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t temp = (a + b + x) & 0xFF;
    return ((temp << 2) | (temp >> 6)) & 0xFF;
}

uint32_t f_function(uint32_t v) {
    uint8_t x[4], y[4];
    for (int i = 0; i < 4; i++) { x[i] = v & 0xFF; v >>= 8; }
    y[2] = g_function(x[3] ^ x[2], x[1] ^ x[0], 1);
    y[3] = g_function(x[3], y[2], 0);
    y[1] = g_function(x[1] ^ x[0], y[2], 0);
    y[0] = g_function(x[0], y[1], 1);
    uint32_t out = 0;
    for (int i = 0; i < 4; i++) out |= (uint32_t)y[i] << (8 * i);
    return out;
}

/* Return the pair of 32 bit halves that existed before the
   rounds that are indicated. Only the keys for those rounds
   are required. */
void peel(uint64_t c, int rounds, uint32_t *keys, uint32_t *outL, uint32_t *outR) {
    uint32_t L = getright(c), R = getleft(c);
    L ^= R;
    for (int r = rounds; r >= 0; r--) {
        uint32_t t = L; L = R; R = t;
        L ^= f_function(t ^ keys[r]);
    }
    *outL = L; *outR = R;
}

